#!/usr/bin/env python3
"""S4 paired baselines (cache-fair).

Cold experiment (paper Table V primary):
  - Disjoint message slices per repetition (no repeated blocks across reps)
  - Boundary cache cleared before every BoundaryGuard mode
  - Report per-rep means for Comp/CU/KB/P50/P95

Warm diagnostic (not Table V primary):
  - Repeat one cold slice without clearing cache to quantify warm bias

Acceptance:
  - ≥5 cold reps; archive fail_closed==0; sparse f=1 CU saving ≥15%
"""

from __future__ import annotations

# --- github publish layout (auto-generated by sync_github_publish.py) ---
import sys
from pathlib import Path as _Path
_GITHUB_ROOT = _Path(__file__).resolve().parents[1]
_BG = _GITHUB_ROOT / "BoundaryGuard"
_EXP = _GITHUB_ROOT / "exp"
for _p in (_BG, _EXP):
    _s = str(_p)
    if _s not in sys.path:
        sys.path.insert(0, _s)
DATA = _GITHUB_ROOT.joinpath("data")
EXP = _EXP
ROOT = _GITHUB_ROOT
# --- end header ---

import argparse
import json
import random
import statistics
import time
from collections import defaultdict
from datetime import datetime, timezone
from pathlib import Path

import relayer_proxy_live as harness
from boundaryguard_proxy import ProxyConfig
from strong_accept_suite import CALL_CU, LOG_CU, run_cost_sweep, run_matrix_reps


ROOT = _GITHUB_ROOT
DATA = DATA / "strong_e2e"
OUT_JSONL = DATA / "s4_paired_samples.jsonl"
OUT_WARM = DATA / "s4_warm_repeat_samples.jsonl"
OUT_SUMMARY = DATA / "s4_summary.json"

MODES = (
    "unchecked",
    "error_fallback",
    "always_dual",
    "boundaryguard_single",
    "boundaryguard_archive",
)

OP_CFG = {
    "primary": "https://mainnet.optimism.io",
    "boundary": "https://optimism.drpc.org",
    "repair": "https://op-pokt.nodies.app",
    "fallback": "https://optimism.drpc.org",
}

ARCHIVE_BOUNDARIES = [
    "https://optimism.drpc.org",
    "https://optimism.gateway.tenderly.co",
    "https://optimism.llamarpc.com",
    "https://optimism-rpc.publicnode.com",
]


def append_jsonl(path: Path, row: dict) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("a") as handle:
        handle.write(json.dumps(row, sort_keys=True) + "\n")


def estimate_cu(mode: str, row: dict) -> float:
    req = int(row.get("requests") or 1)
    if mode == "always_dual":
        return 2 * LOG_CU
    if mode.startswith("boundaryguard"):
        return LOG_CU + 2 * CALL_CU
    return req * LOG_CU


def load_disjoint_slices(chain: str, limit: int, reps: int) -> list[list[dict]]:
    """Return `reps` disjoint slices of `limit` delivered messages each."""
    rows = []
    with harness.MESSAGES.open() as handle:
        for line in handle:
            row = json.loads(line)
            if row["chain"] != chain or not row.get("is_delivered"):
                continue
            rows.append(row)
    rows.sort(key=lambda r: r["origin_block_height"])
    need = limit * reps
    if len(rows) < need:
        raise SystemExit(f"need {need} delivered {chain} messages, have {len(rows)}")
    # Contiguous disjoint slices; optional unused gap distributed between slices.
    leftover = len(rows) - need
    gap = leftover // reps  # may be 0
    slices: list[list[dict]] = []
    cursor = 0
    for i in range(reps):
        chunk = rows[cursor : cursor + limit]
        if len(chunk) < limit:
            raise SystemExit(f"slice underflow at rep {i}: cursor={cursor} have={len(rows)}")
        slices.append(chunk)
        cursor += limit + gap
    heights = [r["origin_block_height"] for sl in slices for r in sl]
    msg_ids = [r.get("message_id") or r.get("id") or f"{r['origin_block_height']}:{r.get('nonce')}" for sl in slices for r in sl]
    if len(msg_ids) != len(set(msg_ids)):
        raise SystemExit("disjoint slice message collision")
    return slices


def run_one_mode(
    mode: str,
    messages: list[dict],
    *,
    single_url: str,
    archive_url: str,
) -> list[dict]:
    if mode == "boundaryguard_single":
        records = harness.run_mode("boundaryguard", messages, OP_CFG, single_url)
        for row in records:
            row["mode"] = mode
        return records
    if mode == "boundaryguard_archive":
        records = harness.run_mode("boundaryguard", messages, OP_CFG, archive_url)
        for row in records:
            row["mode"] = mode
        return records
    return harness.run_mode(mode, messages, OP_CFG, None)


def pctile(xs: list[float], p: float) -> float | None:
    if not xs:
        return None
    xs = sorted(xs)
    return xs[min(len(xs) - 1, int(p * (len(xs) - 1)))]


def summarize_phase(rows: list[dict], *, per_rep_mean: bool) -> dict:
    """If per_rep_mean, average per-rep metrics so Table units match one 200-msg pass."""
    by_rep_mode: dict[tuple[int, str], list] = defaultdict(list)
    for row in rows:
        by_rep_mode[(int(row["rep"]), row["mode"])].append(row)

    mode_reps: dict[str, list[dict]] = defaultdict(list)
    for (rep, mode), items in by_rep_mode.items():
        overhead = [r["proxy_overhead_ms"] for r in items if r.get("proxy_overhead_ms") is not None]
        completed = [r for r in items if r.get("completed")]
        auditable = [r for r in completed if r.get("expected") is not None]
        prefix = sum(1 for r in auditable if r.get("prefix_complete"))
        mode_reps[mode].append(
            {
                "rep": rep,
                "n": len(items),
                "completed": len(completed),
                "fail_closed": len(items) - len(completed),
                "requests": sum(int(r.get("requests") or 1) for r in items),
                "bytes": sum(int(r.get("bytes") or 0) for r in items),
                "cu_est": sum(float(r.get("cu_est") or 0.0) for r in items),
                "boundary_calls": sum(float(r.get("boundary_calls") or 0.0) for r in items),
                "auditable": len(auditable),
                "prefix_complete": prefix,
                "p50_ms": statistics.median(overhead) if overhead else None,
                "p95_ms": pctile(overhead, 0.95),
            }
        )

    modes = {}
    for mode, reps in mode_reps.items():
        def mean(key: str):
            vals = [r[key] for r in reps if r[key] is not None]
            return statistics.fmean(vals) if vals else None

        if per_rep_mean:
            modes[mode] = {
                "reps": len(reps),
                "n": mean("n"),
                "completed": mean("completed"),
                "fail_closed": mean("fail_closed"),
                "completion_rate": (mean("completed") or 0) / (mean("n") or 1),
                "requests": mean("requests"),
                "bytes": mean("bytes"),
                "kb": (mean("bytes") or 0) / 1024.0,
                "cu_est": mean("cu_est"),
                "boundary_calls": mean("boundary_calls"),
                "auditable": mean("auditable"),
                "prefix_complete": mean("prefix_complete"),
                "overhead_ms": {"p50": mean("p50_ms"), "p95": mean("p95_ms")},
                "per_rep": reps,
            }
        else:
            # aggregate all rows (warm diagnostic)
            flat = [r for (_, m), items in by_rep_mode.items() if m == mode for r in items]
            overhead = [r["proxy_overhead_ms"] for r in flat if r.get("proxy_overhead_ms") is not None]
            completed = [r for r in flat if r.get("completed")]
            auditable = [r for r in completed if r.get("expected") is not None]
            prefix = sum(1 for r in auditable if r.get("prefix_complete"))
            modes[mode] = {
                "n": len(flat),
                "completed": len(completed),
                "fail_closed": len(flat) - len(completed),
                "completion_rate": len(completed) / len(flat) if flat else 0.0,
                "requests": sum(int(r.get("requests") or 1) for r in flat),
                "bytes": sum(int(r.get("bytes") or 0) for r in flat),
                "kb": sum(int(r.get("bytes") or 0) for r in flat) / 1024.0,
                "cu_est": sum(float(r.get("cu_est") or 0.0) for r in flat),
                "boundary_calls": sum(int(r.get("boundary_calls") or 0) for r in flat),
                "auditable": len(auditable),
                "prefix_complete": prefix,
                "overhead_ms": {"p50": statistics.median(overhead) if overhead else None, "p95": pctile(overhead, 0.95)},
            }

    dual = modes.get("always_dual", {})
    bg_a = modes.get("boundaryguard_archive", {})
    return {
        "modes": modes,
        "archive_fail_closed": bg_a.get("fail_closed"),
        "archive_completion_rate": bg_a.get("completion_rate"),
        "cu_saving_archive_vs_dual_pct": (
            None
            if not dual.get("cu_est") or not bg_a.get("cu_est")
            else 100.0 * (dual["cu_est"] - bg_a["cu_est"]) / dual["cu_est"]
        ),
    }


def sparse_matrix_gate(reps: int = 30) -> dict:
    matrix = run_matrix_reps(reps)
    f1 = [row for row in matrix["summary"] if row["requested_faults"] == 1]
    mean_f1 = statistics.fmean(row["mean_cu_saving_pct"] for row in f1) if f1 else 0.0
    cost = run_cost_sweep()
    return {
        "matrix_scenarios": matrix["scenarios"],
        "matrix_correct": matrix["correct"],
        "matrix_correct_all": matrix["correct"] == matrix["scenarios"],
        "sparse_f1_mean_cu_saving_pct": mean_f1,
        "sparse_target_pct": 15.0,
        "sparse_pass": mean_f1 >= 15.0,
        "cost_sweep_demotion_frac_n16": cost.get("demotion_frac_n16_alchemy"),
        "note": "Analytic demotion threshold from CU model; not a live provider state-machine experiment.",
        "provenance": "controlled_fault_injection",
    }


def attach_proxy_delta(records: list[dict], delta: dict) -> None:
    n = len(records) or 1
    bnd = int(delta.get("boundary_calls", 0))
    audited = int(delta.get("audited", 0))
    repair = int(delta.get("repair_calls", 0))
    cu_total = audited * LOG_CU + bnd * CALL_CU + repair * LOG_CU
    for row in records:
        row["boundary_calls"] = bnd / n
        row["proxy_audited"] = audited / n
        row["proxy_repair_calls"] = repair / n
        row["cu_est"] = cu_total / n


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--limit", type=int, default=198)
    parser.add_argument("--reps", type=int, default=5)
    parser.add_argument("--port-single", type=int, default=18601)
    parser.add_argument("--port-archive", type=int, default=18602)
    parser.add_argument("--seed", type=int, default=20260810)
    parser.add_argument("--skip-live", action="store_true")
    parser.add_argument("--skip-warm", action="store_true")
    parser.add_argument("--matrix-reps", type=int, default=30)
    args = parser.parse_args()

    DATA.mkdir(parents=True, exist_ok=True)
    for path in (OUT_JSONL, OUT_WARM):
        if path.exists():
            path.unlink()

    matrix = sparse_matrix_gate(args.matrix_reps)
    print("sparse matrix:", json.dumps({k: matrix[k] for k in matrix if "cost" not in k}, indent=2), flush=True)

    cold_rows: list[dict] = []
    warm_rows: list[dict] = []
    if not args.skip_live:
        slices = load_disjoint_slices("optimism", args.limit, args.reps)
        mailbox = harness.normalize(slices[0][0]["origin_mailbox"])
        single_cfg = ProxyConfig(
            chain_id="optimism",
            mailbox=mailbox,
            primary_url=OP_CFG["primary"],
            boundary_url=OP_CFG["boundary"],
            repair_url=OP_CFG["repair"],
            timeout_s=20.0,
            retry_count=1,
            chunk_count=4,
            confirmation_depth=0,
            trace_path=str(DATA / "s4_proxy_trace_single.jsonl"),
        )
        archive_cfg = ProxyConfig(
            chain_id="optimism",
            mailbox=mailbox,
            primary_url=OP_CFG["primary"],
            boundary_url=ARCHIVE_BOUNDARIES[0],
            repair_url=OP_CFG["repair"],
            boundary_urls=ARCHIVE_BOUNDARIES[1:],
            timeout_s=25.0,
            retry_count=1,
            chunk_count=4,
            confirmation_depth=0,
            trace_path=str(DATA / "s4_proxy_trace_archive.jsonl"),
        )
        for p in (DATA / "s4_proxy_trace_single.jsonl", DATA / "s4_proxy_trace_archive.jsonl"):
            if p.exists():
                p.unlink()
        server_s, proxy_s = harness.start_proxy(single_cfg, args.port_single)
        server_a, proxy_a = harness.start_proxy(archive_cfg, args.port_archive)
        single_url = f"http://127.0.0.1:{args.port_single}"
        archive_url = f"http://127.0.0.1:{args.port_archive}"
        try:
            for rep, messages in enumerate(slices):
                rng = random.Random(args.seed + rep)
                order = list(MODES)
                rng.shuffle(order)
                print(
                    f"==== S4 COLD rep {rep+1}/{args.reps} "
                    f"blocks={messages[0]['origin_block_height']}-{messages[-1]['origin_block_height']} "
                    f"order={order} ====",
                    flush=True,
                )
                stats_s0 = dict(proxy_s.stats)
                stats_a0 = dict(proxy_a.stats)
                for mode in order:
                    # Fairness: never carry boundary cache across BG modes/reps.
                    proxy_s.cache.clear()
                    proxy_a.cache.clear()
                    started = time.time()
                    records = run_one_mode(
                        mode, messages, single_url=single_url, archive_url=archive_url
                    )
                    stats_s1 = dict(proxy_s.stats)
                    stats_a1 = dict(proxy_a.stats)
                    if mode == "boundaryguard_single":
                        attach_proxy_delta(records, {k: stats_s1[k] - stats_s0[k] for k in stats_s0})
                        stats_s0 = stats_s1
                    elif mode == "boundaryguard_archive":
                        attach_proxy_delta(records, {k: stats_a1[k] - stats_a0[k] for k in stats_a0})
                        stats_a0 = stats_a1
                    else:
                        for row in records:
                            row["cu_est"] = estimate_cu(mode, row)
                            row["boundary_calls"] = 0
                    for row in records:
                        row["rep"] = rep
                        row["phase"] = "cold_disjoint"
                        row["mode_order"] = order
                        row["gate"] = "S4_paired_baselines"
                        append_jsonl(OUT_JSONL, row)
                        cold_rows.append(row)
                    print(
                        f"cold rep={rep} mode={mode} n={len(records)} "
                        f"elapsed={time.time()-started:.1f}s",
                        flush=True,
                    )

            if not args.skip_warm:
                # Diagnostic only: repeat first slice without clearing after first BG pass.
                messages = slices[0]
                print("==== S4 WARM-REPEAT diagnostic (same slice, cache retained) ====", flush=True)
                proxy_s.cache.clear()
                proxy_a.cache.clear()
                for pass_id, clear in ((0, True), (1, False)):
                    if clear:
                        proxy_a.cache.clear()
                    stats_a0 = dict(proxy_a.stats)
                    started = time.time()
                    records = run_one_mode(
                        "boundaryguard_archive",
                        messages,
                        single_url=single_url,
                        archive_url=archive_url,
                    )
                    stats_a1 = dict(proxy_a.stats)
                    attach_proxy_delta(records, {k: stats_a1[k] - stats_a0[k] for k in stats_a0})
                    for row in records:
                        row["rep"] = pass_id
                        row["phase"] = "warm_repeat_diag"
                        row["cache_cleared_before"] = clear
                        row["gate"] = "S4_warm_repeat_diagnostic"
                        append_jsonl(OUT_WARM, row)
                        warm_rows.append(row)
                    print(
                        f"warm pass={pass_id} clear={clear} n={len(records)} "
                        f"elapsed={time.time()-started:.1f}s "
                        f"bnd={sum(r.get('boundary_calls') or 0 for r in records):.0f}",
                        flush=True,
                    )
        finally:
            server_s.shutdown()
            server_a.shutdown()

    cold = summarize_phase(cold_rows, per_rep_mean=True) if cold_rows else {}
    warm = summarize_phase(warm_rows, per_rep_mean=False) if warm_rows else {}
    reps_done = len({r.get("rep") for r in cold_rows}) if cold_rows else 0
    archive_ok = bool(
        cold
        and (cold.get("archive_fail_closed") or 0) == 0
        and (cold.get("archive_completion_rate") or 0) >= 0.99
    )
    overall = bool(
        matrix["sparse_pass"]
        and matrix["matrix_correct_all"]
        and reps_done >= args.reps
        and archive_ok
    )
    if args.skip_live:
        overall = False

    summary = {
        "gate": "S4_paired_baselines",
        "observed_at": datetime.now(timezone.utc).isoformat(),
        "limit": args.limit,
        "reps": args.reps,
        "reps_done": reps_done,
        "design": {
            "cold": "disjoint message slices; cache cleared before every BG mode",
            "warm": "diagnostic repeat of slice0 with/without clear; not Table V primary",
        },
        "modes": list(MODES),
        "cold": cold,
        "warm_diagnostic": warm,
        "matrix": matrix,
        "overall_pass": overall,
        "strong_target_pass": overall and matrix["sparse_f1_mean_cu_saving_pct"] >= 15.0,
        "next": "S4 cache-fair PASS; update Table V from cold.*" if overall else "S4 cold path incomplete",
        "artifact": str(OUT_JSONL.relative_to(ROOT)),
        "artifact_warm": str(OUT_WARM.relative_to(ROOT)),
        "provenance_live": "live_public_rpc_observation",
        "provenance_matrix": "controlled_fault_injection",
    }
    OUT_SUMMARY.write_text(json.dumps(summary, indent=2, sort_keys=True) + "\n")
    print(json.dumps(summary, indent=2, sort_keys=True), flush=True)
    raise SystemExit(0 if overall else 2)


if __name__ == "__main__":
    main()
